vector<int> sumClosest(vector<int>& arr, int n, int x) {
    int left = 0, right = n - 1;
    int best_diff = INT_MAX;
    int best_sum = -1;
    vector<int> result;
    while (left < right) {
        int sum = arr[left] + arr[right];
        int diff = abs(sum - x);
        if (diff < best_diff || (diff == best_diff && sum > best_sum)) {
            best_diff = diff;
            best_sum = sum;
            result = {arr[left], arr[right]};
        }
        if (sum > x) right--;
        else left++;
    }
    return result;
}

