def frame(arr, border):
    max_len = max(len(s) for s in arr)
    width = max_len + 4
    top_bottom = border * width
    lines = [top_bottom]
    for s in arr:
        lines.append(border + ' ' + s.ljust(max_len) + ' ' + border)
    lines.append(top_bottom)
    return '\n'.join(lines)

