import sys

def main():
    data = sys.stdin.buffer.read().decode()
    lines = data.split('\n')
    n = int(lines[0].strip())

    stack = []
    pos_map = {}
    output = []

    for i in range(1, n + 1):
        line = lines[i].strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == 'E':
            e = parts[1]
            stack.append(e)
            pos_map[e] = len(stack) - 1
        elif parts[0] == 'D':
            r = int(parts[1])
            for _ in range(r):
                e = stack.pop()
                del pos_map[e]
        elif parts[0] == 'S':
            k = int(parts[1])
            events = parts[2:2+k]
            total = len(stack)

            consistent = True
            for e in events:
                if e.startswith('!'):
                    if e[1:] in pos_map:
                        consistent = False
                        break
                else:
                    if e not in pos_map:
                        consistent = False
                        break

            if consistent:
                output.append("Yes")
                continue

            lower = 1
            upper = total
            possible = True

            for e in events:
                if e.startswith('!'):
                    actual = e[1:]
                    if actual in pos_map:
                        c = total - pos_map[actual]
                        if c > lower:
                            lower = c
                else:
                    if e not in pos_map:
                        possible = False
                        break
                    c = total - 1 - pos_map[e]
                    if c < upper:
                        upper = c

            if not possible:
                output.append("Plot Error")
            elif lower <= upper:
                output.append(f"{lower} Just A Dream")
            else:
                output.append("Plot Error")

    sys.stdout.write('\n'.join(output) + '\n')

main()

