int maxSumWithK(int A[], int N, int K) {
    vector<long long> prefix(N + 1, 0);
    for (int i = 0; i < N; i++)
        prefix[i + 1] = prefix[i] + A[i];

    long long minPref = prefix[0];
    long long result = LLONG_MIN;

    for (int j = K - 1; j < N; j++) {
        minPref = min(minPref, prefix[j - K + 1]);
        result = max(result, prefix[j + 1] - minPref);
    }

    return (int)result;
}

