    for(int i = 2; i <= n; i++){
        int j = pi[i-1];
        while(j > 0 && s[i-1] != s[j])
            j = pi[j];
        if(s[i-1] == s[j]) j++;
        pi[i] = j;
    }

    vector<int> occ(n+1, 0);
    for(int i = 1; i <= n; i++)
        occ[pi[i]]++;
    for(int i = n; i >= 1; i--)
        occ[pi[i]] += occ[i];

    vector<int> borders;
    int len = n;
    while(len > 0){
        borders.push_back(len);
        len = pi[len];
    }
    sort(borders.begin(), borders.end());

    cout << borders.size() << "\n";
    for(int L : borders)
        cout << L << " " << occ[L] + 1 << "\n";

    return 0;
}

