    def is_prime(x):
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        for i in range(3, int(x**0.5) + 1, 2):
            if x % i == 0:
                return False
        return True

    bef = n - 1
    while not is_prime(bef):
        bef -= 1

    aft = n + 1
    while not is_prime(aft):
        aft += 1

    return [bef, aft]

