class Solution:
    def minInteger(self, num: str, k: int) -> str:
        n = len(num)
        digit_positions = [[] for _ in range(10)]
        for i, c in enumerate(num):
            digit_positions[int(c)].append(i)
        tree = [0] * (n + 1)
        def update(i, delta):
            i += 1
            while i <= n:
                tree[i] += delta
                i += i & (-i)
        def query(i):
            i += 1
            s = 0
            while i > 0:
                s += tree[i]
                i -= i & (-i)
            return s
        for i in range(n):
            update(i, 1)
        result = []
        pointers = [0] * 10
        for i in range(n):
            for d in range(10):
                if pointers[d] >= len(digit_positions[d]):
                    continue
                pos = digit_positions[d][pointers[d]]
                cost = query(pos) - 1
                if cost <= k:
                    result.append(str(d))
                    k -= cost
                    update(pos, -1)
                    pointers[d] += 1
                    break
        return ''.join(result)

