vector<vector<int>> win(int N, vector<int> powers, int Q, vector<int> queries) {
    sort(powers.begin(), powers.end());
    vector<long long> prefix(N);
    prefix[0] = powers[0];
    for (int i = 1; i < N; i++) {
        prefix[i] = prefix[i - 1] + powers[i];
    }
    vector<vector<int>> result;
    for (int i = 0; i < Q; i++) {
        int idx = upper_bound(powers.begin(), powers.end(), queries[i]) - powers.begin();
        int count = idx;
        long long sum = (idx > 0) ? prefix[idx - 1] : 0;
        result.push_back({count, (int)sum});
    }
    return result;
}

