105031.y_answer:
long largestSumCycle(int n, int[] edge) {
    int[] inDegree = new int[n];
    for (int i = 0; i < n; i++) {
        if (edge[i] != -1) {
            inDegree[edge[i]]++;
        }
    }
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i < n; i++) {
        if (inDegree[i] == 0) {
            queue.add(i);
        }
    }
    while (!queue.isEmpty()) {
        int node = queue.poll();
        if (edge[node] != -1) {
            inDegree[edge[node]]--;
            if (inDegree[edge[node]] == 0) {
                queue.add(edge[node]);
            }
        }
    }
    long maxSum = -1;
    boolean[] visited = new boolean[n];
    for (int i = 0; i < n; i++) {
        if (inDegree[i] > 0 && !visited[i]) {
            long sum = 0;
            int cur = i;
            while (!visited[cur]) {
                visited[cur] = true;
                sum += cur;
                cur = edge[cur];
            }
            maxSum = Math.max(maxSum, sum);
        }
    }
    return maxSum;
}

