import math

def scroller(text, amp, period):
    offsets = [amp * math.sin(2 * math.pi * i / period) for i in range(len(text))]
    min_offset = min(offsets)
    lines = []
    for i, ch in enumerate(text):
        col = round(offsets[i] - min_offset)
        lines.append(' ' * col + ch)
    return '\n'.join(lines)

