def findMaxLen(S):
    max_len = 0
    left = right = 0
    for ch in S:
        if ch == '(':
            left += 1
        else:
            right += 1
        if left == right:
            max_len = max(max_len, 2 * right)
        elif right > left:
            left = right = 0
    left = right = 0
    for ch in reversed(S):
        if ch == ')':
            right += 1
        else:
            left += 1
        if left == right:
            max_len = max(max_len, 2 * left)
        elif left > right:
            left = right = 0
    return max_len

