def bits_war(numbers):
    odd_score = 0
    even_score = 0
    for n in numbers:
        ones = bin(abs(n)).count('1')
        contribution = ones if n > 0 else -ones
        if n % 2 != 0:
            odd_score += contribution
        else:
            even_score += contribution
    if odd_score > even_score:
        return "odds win"
    elif even_score > odd_score:
        return "evens win"
    else:
        return "tie"

