def isPP(n):
    if n < 4:
        return None

    import math
    max_k = int(math.log2(n)) + 1

    for k in range(2, max_k + 1):
        m = round(n ** (1.0 / k))
        for candidate in [m - 1, m, m + 1]:
            if candidate > 1 and candidate ** k == n:
                return [candidate, k]

    return None

