def squareFactor(N):
    count = 1
    d = 2
    while d * d <= N:
        if N % d == 0:
            exp = 0
            while N % d == 0:
                N //= d
                exp += 1
            count *= (exp // 2 + 1)
        d += 1
    if N > 1:
        count *= (1 // 2 + 1)
    return count

