class Solution {
public:
    int maxPathSum(Node* root) {
        int ans = INT_MIN;
        helper(root, ans, true);
        return ans;
    }

    int helper(Node* node, int& ans, bool isRoot) {
        int left = INT_MIN, right = INT_MIN;
        if (node->left)  left  = helper(node->left,  ans, false);
        if (node->right) right = helper(node->right, ans, false);

        int numChildren = (node->left ? 1 : 0) + (node->right ? 1 : 0);
        int down;

        if (numChildren == 0) {
            down = node->data;
        } else if (numChildren == 1) {
            int childDown = (node->left) ? left : right;
            if (isRoot) {
                down = max(node->data, node->data + childDown);
                ans = max(ans, node->data + childDown);
            } else {
                down = node->data + childDown;
            }
        } else {
            down = node->data + max(left, right);
            ans = max(ans, left + node->data + right);
        }

        return down;
    }
};

